#'   \code{"cubic-out"}, \code{"sin-out"}, \code{"exp-out"},
#'   \code{"circle-out"}, \code{"elastic-out"}, \code{"back-out"},
#'   \code{"bounce-out"}, \code{"linear-in-out"}, \code{"quad-in-out"},
